def dedupe_recent(values, limit):
    result = []
    seen = set()
    for val in values:
        if limit == 0:
            if val not in seen:
                seen.add(val)
                result.append(val)
        else:
            if val not in seen:
                seen.add(val)
                result.append(val)
            else:
                if len(result) >= limit:
                    seen.remove(result[-limit])
                if val not in seen:
                    seen.add(val)
                    result.append(val)
    return result
