def parse_int_list(text):
    if text is None or text.strip() == '':
        return []
    parts = text.strip().split(',')
    result = []
    for i, part in enumerate(parts, 1):
        part = part.strip()
        if not part:
            raise ValueError(f"Empty element at position {i}")
        try:
            result.append(int(part))
        except ValueError:
            raise ValueError(f"Invalid integer at position {i}")
    return result
