from collections import defaultdict, deque

def topo(nodes, edges):
    graph = defaultdict(list)
    in_degree = defaultdict(int)
    node_order = {}
    for idx, node in enumerate(nodes):
        node_order[node] = idx

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    queue = deque()
    for node in nodes:
        if in_degree.get(node, 0) == 0:
            queue.append(node)

    result = []
    while queue:
        u = queue.popleft()
        result.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(result) != len(nodes):
        raise ValueError("Cycle detected in the graph")

    return result
